int: n = 20;
array[1..n] of var 0..5: steps;

% Sum of all steps must be exactly 20
constraint sum(steps) = n;

% Each step is either 0, 3, 4, or 5
constraint forall(i in 1..n)(steps[i] in {0, 3, 4, 5});

% Once a 0 occurs, all subsequent steps must be 0
constraint forall(i in 1..n-1)(steps[i] = 0 -> steps[i+1] = 0);

solve satisfy;

% Output the steps array in JSON format
output [
    "{",
    "\"steps\": [" ++ join(", ", [show(steps[i]) | i in 1..n]) ++ "]",
    "}"
];
```

