array[1..5] of int: AGES = [3,5,7,8,10];
array[1..5] of int: COUNTRIES = [1,2,3,4,5]; % 1:Ethiopia, 2:Kazakhstan, 3:Lithuania, 4:Morocco, 5:Yemen
array[1..5] of int: STORIES = [1,2,3,4,5]; % 1:burning_bush, 2:captivity, 3:moses_youth, 4:passover, 5:ten_commandments

array[1..5] of var 1..5: ages;
array[1..5] of var 1..5: countries;
array[1..5] of var 1..5: stories;

constraint all_different(ages) /\ all_different(countries) /\ all_different(stories);

% 1. Debby (child 3) is from Lithuania (country 3)
constraint countries[3] = 3;

% 2. Passover child (story 4) is 2 years older than Bernice (child 1)
constraint exists(c in 1..5)(
    stories[c] = 4 /\ AGES[ages[c]] = AGES[ages[1]] + 2
);

% 3. Yemen (country 5) is younger than Ethiopia (country 1)
constraint exists(y, e in 1..5)(
    countries[y] = 5 /\ countries[e] = 1 /\ AGES[ages[y]] < AGES[ages[e]]
);

% 4. Morocco (country 4) is 3 years older than Ted (child 5)
constraint exists(m in 1..5)(
    countries[m] = 4 /\ AGES[ages[m]] = AGES[ages[5]] + 3
);

% 5. Sammy (child 4) is 3 years older than Moses's youth (story 3)
constraint exists(s in 1..5)(
    stories[s] = 3 /\ AGES[ages[4]] = AGES[ages[s]] + 3
);

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "ages" ++ "\": " ++ show(ages),
        "\"" ++ "children" ++ "\": " ++ show([1,2,3,4,5]),
        "\"" ++ "countries" ++ "\": " ++ show(countries),
        "\"" ++ "stories" ++ "\": " ++ show(stories)
    ]),
    "}"
];
