% Each son's required number of cows (son 0 to 4)
array[0..4] of int: required_counts = [7, 6, 5, 4, 3];
% Each son must have a total milk sum of 65 kg
int: total_sum = 65;

% Decision variable: assignment of each cow (1-25) to a son (0-4)
array[1..25] of var 0..4: cow_assignments;

% Ensure each son gets the correct number of cows
constraint forall(s in 0..4) (
    count(cow_assignments, s) == required_counts[s]
);

% Ensure each son's total milk is exactly 65 kg
constraint forall(s in 0..4) (
    sum(i in 1..25)(i * (cow_assignments[i] == s)) == total_sum
);

solve satisfy;

% Output the cow assignments as a JSON object
output [ "{\"cow_assignments\": " ++ show(cow_assignments) ++ "}" ];
```

