include "globals.mzn";

int: num_people = 8;
array[1..num_people] of set of int: compatible = [
    {2, 3},    % 1
    {1, 6},    % 2
    {1, 4, 7}, % 3
    {2},       % 4
    {2},       % 5
    {5},       % 6
    {8},       % 7
    {3}        % 8
];

array[1..num_people, 1..num_people] of var 0..1: transplants;

% Ensure donors must receive if they donate
constraint forall(i in 1..num_people) (
    sum([transplants[i, j] | j in 1..num_people]) == sum([transplants[k, i] | k in 1..num_people])
);

% Ensure maximum one kidney received per person
constraint forall(j in 1..num_people) (
    sum([transplants[i, j] | i in 1..num_people]) <= 1
);

% Enforce compatibility constraints
constraint forall(i in 1..num_people) (
    forall(j in 1..num_people where not (j in compatible[i])) (
        transplants[i, j] == 0
    )
);

% Maximize total successful transplants
solve maximize sum([transplants[i, j] | i, j in 1..num_people]);

% Output in required JSON format
output [
    "{\"transplants\": [",
    join(",", [
        "[" ++ join(",", [show(transplants[i, j]) | j in 1..num_people]) ++ "]" 
        | i in 1..num_people
    ]),
    "]}"
];
```

