int: n = 4;
int: magic = n * (n*n + 1) div 2;  % Magic constant (34 for n=4)

% Decision variable: 4x4 grid with values 1..16
array[1..n, 1..n] of var 1..n*n: square;

% All numbers must be distinct
constraint all_different([square[i, j] | i in 1..n, j in 1..n]);

% Rows sum to magic constant
constraint forall(i in 1..n) (
    sum([square[i, j] | j in 1..n]) = magic
);

% Columns sum to magic constant
constraint forall(j in 1..n) (
    sum([square[i, j] | i in 1..n]) = magic
);

% Diagonals sum to magic constant
constraint sum([square[i, i] | i in 1..n]) = magic;
constraint sum([square[i, n + 1 - i] | i in 1..n]) = magic;

solve satisfy;

% Output the square as a JSON object with key "square"
output ["{\"square\": " ++ show([ [square[i, j] | j in 1..n] | i in 1..n ]) ++ "}"];
```

