include "globals.mzn";

int: n = 8;
array[1..n] of array[int] of int: adjacency_list = [
    [2, 3, 7],
    [1, 4, 8],
    [1, 4, 5],
    [2, 3, 6],
    [3, 6, 7],
    [4, 5, 8],
    [1, 5, 8],
    [2, 6, 7]
];

array[1..n] of var bool: nodes;

% Ensure no adjacent nodes are both selected
constraint forall(i in 1..n, j in adjacency_list[i]) (
    not (nodes[i] and nodes[j])
);

% Ensure maximality: unselected nodes have at least one selected neighbor
constraint forall(i in 1..n) (
    nodes[i] or exists(j in adjacency_list[i])(nodes[j])
);

solve satisfy;

output [
    "{",
    "\"nodes\": [" ++ join(", ", [show(nodes[i]) | i in 1..n]) ++ "]",
    "}"
];
```

