% Input data
jobs_data = [
    [ [0,3], [1,2], [2,2] ],  % Job 0
    [ [0,2], [2,1], [1,4] ],  % Job 1
    [ [1,4], [2,3] ]          % Job 2
];

int: n_jobs = length(jobs_data);
array[0..n_jobs-1] of int: n_tasks = [ length(jobs_data[j]) | j in 0..n_jobs-1 ];
int: max_tasks = max(n_tasks);

array[0..n_jobs-1, 0..max_tasks-1] of int: machines = array2d(0..n_jobs-1, 0..max_tasks-1,
    [ if t < n_tasks[j] then jobs_data[j][t][0] else -1 endif | j in 0..n_jobs-1, t in 0..max_tasks-1 ]);
array[0..n_jobs-1, 0..max_tasks-1] of int: durations = array2d(0..n_jobs-1, 0..max_tasks-1,
    [ if t < n_tasks[j] then jobs_data[j][t][1] else 0 endif | j in 0..n_jobs-1, t in 0..max_tasks-1 ]);

set of int: machines_used = { machines[j,t] | j in 0..n_jobs-1, t in 0..n_tasks[j]-1 };

array[0..n_jobs-1, 0..max_tasks-1] of var 0..int: start_times;
var int: makespan = max( [ start_times[j,t] + durations[j,t] | j in 0..n_jobs-1, t in 0..n_tasks[j]-1 ] );

% Precedence constraints within each job
constraint forall(j in 0..n_jobs-1) (
    forall(t in 1..n_tasks[j]-1) (
        start_times[j,t] >= start_times[j,t-1] + durations[j,t-1]
    )
);

% Disjunctive constraints for each machine
constraint forall(m in machines_used) (
    disjunctive(
        [ start_times[j,t] | j in 0..n_jobs-1, t in 0..n_tasks[j]-1 where machines[j,t] == m ],
        [ durations[j,t] | j in 0..n_jobs-1, t in 0..n_tasks[j]-1 where machines[j,t] == m ]
    )
);

solve minimize makespan;

output [ "{\"makespan\": " ++ show(makespan) ++ "}" ];
