    1,2,3,
    4,5,6,
    7,8,0
]);

array[0..N, 1..3, 1..3] of var 0..8: state;
array[0..N] of var 1..3: empty_row;
array[0..N] of var 1..3: empty_col;

constraint forall(i in 1..3, j in 1..3) (
    state[0, i, j] = puzzle_start[i, j]
);

constraint forall(i in 1..3, j in 1..3) (
    state[N, i, j] = puzzle_end[i, j]
);

constraint forall(s in 0..N) (
    forall(i in 1..3, j in 1..3) (
        (i = empty_row[s] /\ j = empty_col[s]) <-> (state[s, i, j] = 0)
    )
);

constraint forall(s in 0..N-1) (
    abs(empty_row[s+1] - empty_row[s]) + abs(empty_col[s+1] - empty_col[s]) = 1
);

constraint forall(s in 0..N-1) (
    forall(i in 1..3, j in 1..3) (
        if (i != empty_row[s] \/ j != empty_col[s]) /\
           (i != empty_row[s+1] \/ j != empty_col[s+1]) then
            state[s+1, i, j] = state[s, i, j]
        else
            if (i = empty_row[s] /\ j = empty_col[s]) then
                state[s+1, i, j] = state[s, empty_row[s+1], empty_col[s+1]]
            else
                state[s+1, i, j] = 0
