    join(", ", [
        "[" ++ join(", ", [
            "[" ++ join(", ", [show(state[s, i, j]) | j in 1..3]) ++ "]" 
            | i in 1..3
        ]) ++ "]"
        | s in 1..N
    ]) ++ "]}"
];
