include "globals.mzn";

% People are represented as indices: 0 - Agatha, 1 - Butler, 2 - Charles
set of int: People = 0..2;

% Decision variables
var People: killer;
array[People, People] of var bool: hates;
array[People, People] of var bool: richer;

% Constraints

% Agatha's hate is fixed (hates herself and Charles, not the Butler)
constraint hates[0,0] == true;
constraint hates[0,1] == false;
constraint hates[0,2] == true;

% Charles hates no one that Agatha hates (Agatha hates 0 and 2)
constraint hates[2,0] == false;
constraint hates[2,2] == false;

% Butler hates everyone Agatha hates (0 and 2)
constraint hates[1,0] == true;
constraint hates[1,2] == true;

% Butler hates everyone not richer than Agatha
constraint forall(j in People) (
    (not richer[j,0]) -> hates[1,j]
);

% No one hates everyone
constraint forall(i in People) (
    exists(j in People)(not hates[i,j])
);

% Richer matrix is irreflexive (no one is richer than themselves)
constraint forall(i in People)(not richer[i,i]);

% Richer matrix is antisymmetric (if i is richer than j, j cannot be richer than i)
constraint forall(i, j in People where i != j)(
    richer[i,j] -> not richer[j,i]
);

% Killer must hate Agatha and not be richer than her
constraint hates[killer, 0] == true;
constraint not richer[killer, 0];

solve satisfy;

% Output the killer's index as JSON
output [
    "{",
    "\"killer\": " ++ show(killer),
    "}"
];
```

