% Input data
int: n_slots = 9;
int: n_templates = 2;
int: n_var = 7;
array[1..n_var] of int: demand = [250, 255, 260, 500, 500, 800, 1100];

% Decision variables: layout[t][v] is the number of slots for variation v on template t
array[1..n_templates, 1..n_var] of var 0..n_slots: layout;
% production[t] is the number of sheets printed using template t
array[1..n_templates] of var int: production;

% Each template must use exactly n_slots slots
constraint forall(t in 1..n_templates) (
    sum([layout[t, v] | v in 1..n_var]) = n_slots
);

% Demand for each variation must be met
constraint forall(v in 1..n_var) (
    sum([layout[t, v] * production[t] | t in 1..n_templates]) >= demand[v]
);

% Production cannot be negative
constraint forall(t in 1..n_templates) (production[t] >= 0);

% Minimize total production
solve minimize sum(production);

% Output JSON with production and layout
output [
    "{",
    join(",", [
        "\"production\": [" ++ join(",", [show(production[t]) | t in 1..n_templates]) ++ "]",
        "\"layout\": [" ++ join(",", ["[" ++ join(",", [show(layout[t, v]) | v in 1..n_var]) ++ "]" | t in 1..n_templates]) ++ "]"
    ]),
    "}"
];
