% Input data
int: n = 10;  % Length of the binary sequence

% Decision Variables: binary sequence with values +1 or -1
array[0..n-1] of var -1..1: S;

% Autocorrelations C_k for k=1..n-1 (non-periodic boundary conditions)
array[1..n-1] of var int: C = [
    sum([S[i] * S[i + k] | i in 0..(n - k - 1)])
    | k in 1..n-1
];

% Energy to minimize: sum of squares of autocorrelations
var int: E = sum([c * c | c in C]);

% Objective: minimize energy
solve minimize E;

% Output JSON with sequence and energy
output [
    "{",
    "\"sequence\": [", join(", ", [show(S[i]) | i in 0..n-1]), "], ",
    "\"E\": ", show(E),
    "}"
];
