int: size = 10;  % Number of marks on the Golomb ruler

array[1..size] of var int: a;  % Positions of the marks

constraint a[1] == 0;  % First mark is always 0
constraint forall(i in 1..size-1)(a[i] < a[i+1]);  % Marks must be strictly increasing

% All pairwise differences must be distinct
array[int] of var int: diffs = [a[j] - a[i] | i in 1..size-1, j in i+1..size];
constraint alldifferent(diffs);

% Symmetry-breaking constraint: first difference < last difference
constraint a[2] < (a[size] - a[size-1]);

% Objective: minimize the total length (last mark)
solve minimize a[size];

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"marks\": " ++ show(a),
        "\"length\": " ++ show(a[size])
    ]),
    "}"
];
