include "globals.mzn";

int: n_weeks = 4;
int: n_groups = 3;
int: group_size = 3;
int: n_golfers = n_groups * group_size;

set of int: Golfers = 1..n_golfers;
set of int: Weeks = 1..n_weeks;
set of int: Groups = 1..n_groups;
set of int: Positions = 1..group_size;

array[Weeks, Groups, Positions] of var Golfers: assign;

% Fix first week to break symmetry
constraint forall(g in Groups, i in Positions) (
    if g == 1 then assign[1, g, i] = i 
    elseif g == 2 then assign[1, g, i] = group_size + i 
    else assign[1, g, i] = 2*group_size + i 
    endif
);

% Order within groups to break symmetry
constraint forall(w in Weeks, g in Groups, i in 1..group_size-1) (
    assign[w, g, i] < assign[w, g, i+1]
);

% Each group has distinct golfers
constraint forall(w in Weeks, g in Groups) (
    all_different([assign[w, g, i] | i in Positions])
);

% All golfers participate each week
constraint forall(w in Weeks) (
    all_different([assign[w, g, i] | g in Groups, i in Positions])
);

% No pair plays together more than once
constraint forall(a, b in Golfers where a < b) (
    sum([ exists(g in Groups) (exists(i in Positions)(assign[w, g, i] == a) 
        /\ exists(j in Positions)(assign[w, g, j] == b) | w in Weeks ]) <= 1
);

solve satisfy;

output [
    "{\n  \"assign\": [\n",
    join(",\n", [
        "    [ " ++ join(", ", [
            "[ " ++ join(", ", [ show(assign[w, g, i]) | i in Positions ]) ++ " ]"
            | g in Groups
        ]) ++ " ]"
        | w in Weeks
    ]),
    "\n  ]\n}"
];
