array[1..rows, 1..row_rule_len] of int: row_rules = array2d(1..rows, 1..row_rule_len, [
    0, 1, 0, 2, 4, 4, 0,12, 0, 8, 0, 9, 3, 4, 2, 2
]);
int: cols = 13;
int: col_rule_len = 2;
array[1..cols, 1..col_rule_len] of int: col_rules = array2d(1..cols, 1..col_rule_len, [
    0, 2, 2, 1, 3, 2, 0, 6, 1, 4, 0, 3, 0, 4, 0, 4, 0, 4, 0, 5, 0, 4, 1, 3, 0, 2
]);

array[1..rows, 1..cols] of var bool: board;

function tuple(int: n_states, array[int,int] of int: transitions, set of int: accepting) = make_nonogram_dfa(array[int] of int: pattern) {
    int: len = length(pattern);
    int: q = 1 + sum([b + 1 | b in pattern where b > 0]);
    array[1..q, 0..1] of int: transitions = array2d(1..q, 0..1, 0);
    set of int: accepting;

    transitions[1, 0] = 1;
    transitions[1, 1] = 2;
    int: s = 2;
    int: block_num = 1;
    for (i in 1..len) where (pattern[i] > 0) {
        int: block_size = pattern[i];
        for (j in 1..block_size) {
            transitions[s, 1] = if j < block_size then s + 1 else (if block_num < sum([1 | k in 1..len where pattern[k] > 0]) then s + 1 else s + 1);
            s := s + 1;
        }
        if block_num < sum([1 | k in 1..len where pattern[k] > 0]) {
            transitions[s, 0] = s + 1;
            s := s + 1;
            block_num := block_num + 1;
        }
    }
    transitions[s, 0] = s;
    accepting = {s};

    (s, transitions, accepting);
}

constraint forall(i in 1..rows) (
    let {
        array[int] of int: r_rule = [row_rules[i,j] | j in 1..row_rule_len where row_rules[i,j] != 0],
        tuple(int: ns, array[int,int] of int: t, set of int: a) = make_nonogram_dfa(r_rule),
        array[1..cols] of var bool: row = [board[i,j] | j in 1..cols]
    } in regular(row, ns, t, 1, a)
);

constraint forall(j in 1..cols) (
    let {
        array[int] of int: c_rule = [col_rules[j,k] | k in 1..col_rule_len where col_rules[j,k] != 0],
        tuple(int: ns, array[int,int] of int: t, set of int: a) = make_nonogram_dfa(c_rule),
        array[1..rows] of var bool: col = [board[i,j] | i in 1..rows]
    } in regular(col, ns, t, 1, a)
);

solve satisfy;

output [
    "{\"board\": [" ++ 
    join(",\n ", ["[" ++ join(",", [show(board[i,j]) | j in 1..cols]) ++ "]" | i in 1..rows]) ++
    "]}"
];
