include "globals.mzn";

int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

set of int: BOATS = 1..n_boats;
set of int: PERIODS = 1..n_periods;

% Decision Variables
array[BOATS] of var bool: is_host;
array[BOATS, PERIODS] of var BOATS: visits;

% Hosts remain on their boat in all periods
constraint forall(b in BOATS, p in PERIODS where is_host[b])(
    visits[b, p] == b
);

% Guests must visit a host in each period
constraint forall(b in BOATS, p in PERIODS where not is_host[b])(
    is_host[visits[b, p]]
);

% Capacity constraints for hosts
constraint forall(h in BOATS, p in PERIODS where is_host[h])(
    sum(b in BOATS where b != h) (crew_size[b] * (visits[b, p] == h)) + crew_size[h] <= capacity[h]
);

% Guests cannot revisit the same host
constraint forall(b in BOATS where not is_host[b])(
    all_different([visits[b, p] | p in PERIODS])
);

% Guest crews cannot meet more than once
constraint forall(b1, b2 in BOATS where b1 < b2 /\ not is_host[b1] /\ not is_host[b2])(
    sum(p in PERIODS)(visits[b1, p] == visits[b2, p]) <= 1
);

% Minimize number of host boats
solve minimize sum(is_host);

% Output JSON with visits and is_host
output [
    "{",
    join(",", [
        "\"visits\": [" ++ 
            join(",", [
                "[" ++ join(",", [show(visits[b, p]) | p in PERIODS]) ++ "]" 
                | b in BOATS
            ]) ++ 
        "]",
        "\"is_host\": [" ++ join(",", [show(is_host[b]) | b in BOATS]) ++ "]"
    ]),
    "}"
];
