% Each ball must be in exactly one box
constraint forall(i in BALLS) (
    sum(j in BOXES)(M[i,j]) = 1
);

% For each triple (x,y,z) and box j, not all in the same box
constraint forall(t in 1..78, j in BOXES) (
    M[triples[t,1], j] + M[triples[t,2], j] + M[triples[t,3], j] <= 2
);

% Determine the box assignment for each ball
array[BALLS] of var int: balls = [sum(j in BOXES)(j * M[i,j]) | i in BALLS];

solve satisfy;

% Output the balls' box assignments as a JSON object
output [
    "{\"balls\": [" ++ 
    join(", ", [show(fix(balls[i])) | i in BALLS]) ++ 
    "]}\n"
];
