constraint forall(w in 1..num_weeks) (
    all_different([home[w, p] | p in 1..num_periods] ++ [away[w, p] | p in 1..num_periods])
);

% Each team appears at most twice in the same period across all weeks
constraint forall(p in 1..num_periods, t in 0..n_teams-1) (
    count([home[w, p] | w in 1..num_weeks] ++ [away[w, p] | w in 1..num_weeks], t) <= 2
);

% Each pair plays exactly once in each direction (home and away)
constraint forall(a, b in 0..n_teams-1 where a != b) (
    sum([home[w, p] == a /\ away[w, p] == b | w in 1..num_weeks, p in 1..num_periods]) == 1
);

solve satisfy;

output [
    "{",
    join(",", [
        "\"home\": [" ++
            join(",\n            ", [
                "[" ++ join(",", [show(home[w, p]) | p in 1..num_periods]) ++ "]" 
