        "\"away\": [" ++
            join(",\n            ", [
                "[" ++ join(",", [show(away[w, p]) | p in 1..num_periods]) ++ "]" 
                | w in 1..num_weeks
            ]) ++ "]"
    ]),
    "}"
];
