int: N = 10;

% Degree variables (non-increasing, each divisible by 3, sum mod 12)
array[1..N] of var {3, 6, 9}: d;

% Adjacency matrix (symmetric, no loops)
array[1..N, 1..N] of var 0..1: adj;

% Degree sequence constraints
constraint forall(i in 1..N-1)(d[i] >= d[i+1]);
constraint sum(d) mod 12 == 0;

% Adjacency matrix constraints
constraint forall(i in 1..N)(adj[i, i] == 0);  % No loops
constraint forall(i, j in 1..N where i < j)(adj[i, j] == adj[j, i]);  % Symmetry
constraint forall(i in 1..N)(sum([adj[i, j] | j in 1..N]) == d[i]);  % Degree match

% Diamond-free constraint (no 4-vertex induced subgraph with ≥5 edges)
constraint forall(a in 1..N-3, b in a+1..N-2, c in b+1..N-1, d_ind in c+1..N) (
    adj[a, b] + adj[a, c] + adj[a, d_ind] + adj[b, c] + adj[b, d_ind] + adj[c, d_ind] <= 4
);

solve satisfy;

% Output the adjacency matrix in JSON format
output [
    "{" ++
    "\"matrix\": [" ++
    join(",\n ", [ "[" ++ join(", ", [show(adj[i, j]) | j in 1..N]) ++ "]" | i in 1..N ]) ++
    "]" ++
    "}"
];
```

