    sum(a in 1..num_faces, b in 1..num_faces)(dice[A,a] > dice[B,b]) 
    > 
    sum(a in 1..num_faces, b in 1..num_faces)(dice[B,b] > dice[A,a])
);

solve satisfy;

output [
    "{\"dice\": " ++ show([ [fix(dice[d, f]) | f in 1..num_faces ] | d in 1..num_dice ]) ++ "}"
];
