include "globals.mzn";

int: num_warehouses = 4;
int: num_regions = 3;

array[1..num_warehouses] of int: fixed_costs = [400, 500, 300, 150];
array[1..num_regions] of int: demands = [80, 70, 40];
array[1..num_warehouses, 1..num_regions] of int: shipping_costs = [
    [20, 40, 50],   % New York
    [48, 15, 26],   % Los Angeles
    [26, 35, 18],   % Chicago
    [24, 50, 35]    % Atlanta
];
int: max_shipping = 100;

% Decision Variables
array[1..num_warehouses] of var bool: open_warehouse;
array[1..num_warehouses, 1..num_regions] of var 0..max_shipping: ships;

% Constraints
% 1. If NY is open, LA must be open
constraint open_warehouse[1] -> open_warehouse[2];

% 2. At most three warehouses can be open
constraint sum(open_warehouse) <= 3;

% 3. Either LA or Atlanta must be open
constraint open_warehouse[2] \/ open_warehouse[4];

% 4. Demand must be met for each region
constraint forall(r in 1..num_regions) (
    sum(w in 1..num_warehouses)(ships[w, r]) = demands[r]
);

% 5. Shipping only allowed from open warehouses
constraint forall(w in 1..num_warehouses, r in 1..num_regions) (
    ships[w, r] <= max_shipping * bool2int(open_warehouse[w])
);

% Objective: Minimize total cost
var int: total_cost = sum(w in 1..num_warehouses)(fixed_costs[w] * bool2int(open_warehouse[w])) 
    + sum(w in 1..num_warehouses, r in 1..num_regions)(shipping_costs[w, r] * ships[w, r]);

solve minimize total_cost;

output [
    "{",
    join(", ", [
        "\"total_cost\": " ++ show(total_cost),
        "\"open_warehouse\": [" ++ join(", ", [show(open_warehouse[w]) | w in 1..num_warehouses]) ++ "]",
        "\"ships\": [" ++ join(", ", [ "[" ++ join(", ", [show(ships[w, r]) | r in 1..num_regions]) ++ "]" | w in 1..num_warehouses ]) ++ "]"
    ]),
    "}"
];
